-- 회원이 늘면

@Test
void eager_많으면() {
    for (int i = 0; i < 100; i++) {
        Team t = new Team("t" + i); em.persist(t);
        em.persist(new Member("m" + i, i, t));
    }
    em.flush(); em.clear();

    long n = counter.count(() ->
        em.createQuery("select m from Member m", Member.class)
          .getResultList());
    System.out.println("쿼리 " + n + "개");
}

