-- 프록시와 원본은 다른 객체다

@Test
void 동일성() {
    Member m = em.find(Member.class, 1L);
    Team proxy = m.getTeam();
    Team real = em.find(Team.class, 1L);

    System.out.println("프록시 클래스: " + proxy.getClass().getSimpleName());
    System.out.println("원본 클래스  : " + real.getClass().getSimpleName());
    System.out.println("== 비교      : " + (proxy == real));
    System.out.println("instanceof   : " + (proxy instanceof Team));
    System.out.println("getClass 비교: " +
            (proxy.getClass() == real.getClass()));
}

